body{background:#f8f1df;color:#2f4a12}
.shop-page{color:#2f4a12}.shop-page .sec-title{padding:38px 20px 30px;margin:0 auto 22px;border-radius:12px;background:linear-gradient(135deg,#4d7c0f22,#78350f22);border:1px solid rgba(77,124,15,.45);text-align:center}
.shop-page .sec-title h1{color:#2f4a12}.shop-page .sec-title p{color:#6b5b3a}.shop-page .sec-title .kicker{color:#4d7c0f;font-weight:800}
