.shop-page .grid .card{background:#fffaf0!important;border:1px solid rgba(77,124,15,.45)!important;border-radius:10px!important;box-shadow:none!important;color:#2f4a12!important;overflow:hidden;}.shop-page .grid .card .thumb{background:transparent}.shop-page .grid .card h3{color:#2f4a12!important}.shop-page .grid .card .price{color:#4d7c0f!important}.shop-page .grid .card .old,.shop-page .grid .card .stars small{color:#6b5b3a!important}
